-- Generado desde data/questions/starter.json. No copiar a los clientes.
begin;
on conflict(id) do update set category_id=excluded.category_id,difficulty=excluded.difficulty,prompt=excluded.prompt,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation;
commit;
-- Verificar el contenido real insertado por categoría y dificultad:
select c.name,q.difficulty,count(*) from public.questions q join public.categories c on c.id=q.category_id where q.active group by c.name,q.difficulty order by c.name,q.difficulty;
